#!/usr/bin/env python3
"""Offline tests for update_history.py: python3 .github/scripts/test_update_history.py."""

import importlib.util
import io
import json
from pathlib import Path
import subprocess
import tempfile
import unittest
from contextlib import redirect_stderr, redirect_stdout
from unittest import mock


SCRIPT = Path(__file__).with_name("update_history.py")
spec = importlib.util.spec_from_file_location("update_history", SCRIPT)
uh = importlib.util.module_from_spec(spec)
spec.loader.exec_module(uh)


CHANGELOG = """# Changelog

All notable changes to RC2FX are documented here.

## [1.3.0] - 2026-11-07

### Features

- Add the fourth thing

## [1.2.0] - 2026-11-06

### Features

- Add the third thing

## [1.1.0] - 2026-11-05

### Features

- Add the second thing

### Bug fixes

- Fix the second thing

## [1.0.0] - 2026-11-04

### Features

- Add the first thing

<!-- generated by git-cliff -->
"""

MIXER_NOTES = """# RC2FX mixer software notes

Notes for published mixer versions.

## [1.0.0]

- First published mixer software.
"""


def release(version, *, draft=False, prerelease=False, date="2026-11-04", tag=None):
    return {
        "tag_name": tag or f"v{version}",
        "draft": draft,
        "prerelease": prerelease,
        "published_at": f"{date}T12:00:00Z",
    }


def mappings(*entries):
    return {app: uh.Mapping(mixer, protocol) for app, mixer, protocol in entries}


class HistoryTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name) / "repo"
        self.put("CHANGELOG.md", CHANGELOG)
        self.put("docs/updates/source/mixer-notes.md", MIXER_NOTES)
        self.default_mappings = mappings(
            ("1.0.0", "1.0.0", 1),
            ("1.1.0", "1.0.0", 1),
            ("1.2.0", "1.0.0", 1),
        )

    def put(self, name, text):
        path = self.root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)

    def build(self, *entries, mappings=None, use_git=False):
        published = uh.normalize_published(list(entries), "test")
        return uh.build_bundle(
            self.root,
            published,
            mappings=None
            if use_git
            else (self.default_mappings if mappings is None else mappings),
        )

    def init_git(self):
        subprocess.run(["git", "init", "-b", "main"], cwd=self.root, check=True,
                       capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test"], cwd=self.root, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.invalid"],
                       cwd=self.root, check=True)
        subprocess.run(["git", "add", "."], cwd=self.root, check=True)
        subprocess.run(["git", "commit", "-m", "Initial"], cwd=self.root, check=True,
                       capture_output=True)

    def tag(self, version):
        subprocess.run(["git", "tag", f"v{version}"], cwd=self.root, check=True)

    def test_only_published_stable_app_releases_are_listed_newest_first(self):
        bundle = self.build(
            release("1.0.0"),
            release("1.1.0", date="2026-11-05"),
            release("1.2.0", draft=True, date="2026-11-06"),
            release("1.3.0", prerelease=True, date="2026-11-07"),
            release("0.9.0", tag="mixer-v0.9.0"),
        )
        app = bundle.feed["app"]
        self.assertEqual([r["version"] for r in app["releases"]], ["1.1.0", "1.0.0"])
        self.assertEqual(app["latest"], "1.1.0")
        self.assertEqual(app["historyStart"], "1.0.0")
        self.assertEqual(app["releases"][0]["date"], "2026-11-05")
        self.assertEqual(
            app["releases"][0]["releaseUrl"],
            "https://github.com/ibanks42/rc2fx/releases/tag/v1.1.0",
        )
        self.assertNotIn("Add the third thing", bundle.app_page)
        self.assertNotIn("Add the fourth thing", bundle.app_page)
        self.assertNotIn("Add the third thing", json.dumps(bundle.feed))

    def test_the_newest_published_release_must_have_notes(self):
        self.put("CHANGELOG.md", "# Changelog\n\n## [1.0.0] - 2026-11-04\n\n- First\n")
        with self.assertRaisesRegex(uh.Problem, "newest published release"):
            self.build(release("1.1.0"))

    def test_an_older_published_release_without_notes_is_explicit(self):
        self.put("CHANGELOG.md", "# Changelog\n\n## [1.2.0] - 2026-11-06\n\n- Third\n")
        bundle = self.build(release("1.0.0"), release("1.2.0"))
        entries = {r["version"]: r for r in bundle.feed["app"]["releases"]}
        self.assertEqual(list(entries), ["1.2.0", "1.0.0"])
        self.assertIsNone(entries["1.0.0"]["notesMarkdown"])
        self.assertFalse(bundle.feed["app"]["historyComplete"])
        self.assertIn("Notes for some releases are unavailable", bundle.app_page)
        self.assertIn("No published notes are available for this release.", bundle.app_page)

    def test_unknown_mixer_mapping_is_null_and_never_guessed(self):
        bundle = self.build(release("1.0.0"), mappings={})
        entry = bundle.feed["app"]["releases"][0]
        self.assertIsNone(entry["mixerVersion"])
        self.assertIsNone(entry["protocolVersion"])
        self.assertEqual(bundle.feed["mixer"]["releases"], [])
        self.assertIsNone(bundle.feed["mixer"]["latest"])
        self.assertIsNone(bundle.feed["mixer"]["historyStart"])
        self.assertFalse(bundle.feed["mixer"]["historyComplete"])
        self.assertIn("Bundled RC2FX mixer software: unknown", bundle.app_page)
        self.assertIn("No RC2FX mixer software history is known", bundle.mixer_page)
        self.assertTrue(any("no recorded bundled mixer version" in w for w in bundle.warnings))

    def test_mixer_notes_are_never_invented_and_first_app_is_the_oldest(self):
        bundle = self.build(
            release("1.0.0", date="2026-11-01"),
            release("1.1.0", date="2026-11-02"),
            release("1.2.0", date="2026-11-03"),
            mappings=mappings(
                ("1.0.0", "1.0.0", 1),
                ("1.1.0", "1.0.0", 2),
                ("1.2.0", "1.1.0", 2),
            ),
        )
        mixer = bundle.feed["mixer"]
        self.assertEqual([r["version"] for r in mixer["releases"]], ["1.1.0", "1.0.0"])
        newer, older = mixer["releases"]
        self.assertIsNone(newer["notesMarkdown"])
        self.assertEqual(newer["firstAppVersion"], "1.2.0")
        self.assertEqual(newer["date"], "2026-11-03")
        self.assertEqual(older["notesMarkdown"], "- First published mixer software.")
        self.assertEqual(older["firstAppVersion"], "1.0.0")
        self.assertEqual(older["date"], "2026-11-01")
        self.assertEqual(mixer["latest"], "1.1.0")
        self.assertEqual(mixer["historyStart"], "1.0.0")
        self.assertFalse(mixer["historyComplete"])
        self.assertIn("notes for some versions are unavailable", bundle.mixer_page)
        self.assertIn("No published notes are available for this mixer version.", bundle.mixer_page)

    def test_app_prepared_versions_fold_into_the_next_published_release(self):
        bundle = self.build(release("1.0.0"), release("1.2.0"))
        self.assertEqual(
            [r["version"] for r in bundle.feed["app"]["releases"]], ["1.2.0", "1.0.0"]
        )
        notes = bundle.feed["app"]["releases"][0]["notesMarkdown"]
        self.assertIn("**Prepared as v1.1.0, not published.**", notes)
        self.assertIn("Add the second thing", notes)
        self.assertIn("Add the third thing", notes)
        self.assertNotIn("Add the fourth thing", notes)
        self.assertNotIn("1.1.0\"", json.dumps(bundle.feed["app"]["releases"]))
        self.assertIn("**Prepared as v1.1.0, not published.**", bundle.app_page)

    def test_multiple_prepared_versions_fold_in_chronological_order(self):
        self.put(
            "CHANGELOG.md",
            "# Changelog\n\n"
            "## [1.2.0] - 2026-11-06\n\n- Third\n\n"
            "## [1.1.1] - 2026-11-05\n\n- Middle\n\n"
            "## [1.1.0] - 2026-11-05\n\n- Earlier\n\n"
            "## [1.0.0] - 2026-11-04\n\n- First\n",
        )
        bundle = self.build(release("1.0.0"), release("1.2.0"))
        notes = bundle.feed["app"]["releases"][0]["notesMarkdown"]
        self.assertLess(notes.index("Prepared as v1.1.0"), notes.index("Prepared as v1.1.1"))
        self.assertLess(notes.index("Prepared as v1.1.1"), notes.index("Third"))
        self.assertLess(notes.index("Earlier"), notes.index("Middle"))

    def test_prepared_versions_above_the_newest_published_are_hidden(self):
        bundle = self.build(release("1.0.0"), release("1.1.0"))
        self.assertNotIn("Add the third thing", bundle.app_page)
        self.assertNotIn("Add the fourth thing", bundle.app_page)
        self.assertNotIn("Prepared as v1.2.0", bundle.app_page)
        self.assertNotIn("Prepared as v1.3.0", bundle.app_page)

    def test_mixer_prepared_versions_fold_into_the_next_shipped_version(self):
        self.put(
            "docs/updates/source/mixer-notes.md",
            MIXER_NOTES
            + "\n## [1.1.0]\n\n- Prepared mixer change.\n"
            + "\n## [1.2.0]\n\n- Shipped mixer change.\n",
        )
        bundle = self.build(
            release("1.0.0"), release("1.2.0"),
            mappings=mappings(("1.0.0", "1.0.0", 1), ("1.2.0", "1.2.0", 2)),
        )
        mixer = bundle.feed["mixer"]["releases"]
        self.assertEqual([r["version"] for r in mixer], ["1.2.0", "1.0.0"])
        notes = mixer[0]["notesMarkdown"]
        self.assertIn("**Prepared as mixer 1.1.0, not published.**", notes)
        self.assertIn("Prepared mixer change", notes)
        self.assertIn("Shipped mixer change", notes)
        self.assertNotIn('"1.1.0"', json.dumps(mixer))
        self.assertIn("**Prepared as mixer 1.1.0, not published.**", bundle.mixer_page)

    def test_missing_target_mixer_notes_do_not_swallow_prepared_notes(self):
        self.put(
            "docs/updates/source/mixer-notes.md",
            MIXER_NOTES + "\n## [1.1.0]\n\n- Prepared mixer change.\n",
        )
        bundle = self.build(
            release("1.0.0"), release("1.2.0"),
            mappings=mappings(("1.0.0", "1.0.0", 1), ("1.2.0", "1.2.0", 2)),
        )
        entry = next(r for r in bundle.feed["mixer"]["releases"] if r["version"] == "1.2.0")
        self.assertIsNone(entry["notesMarkdown"])
        self.assertIn("No published notes are available for this mixer version.", bundle.mixer_page)
        self.assertNotIn("Prepared mixer change", bundle.mixer_page)
        self.assertTrue(any("could not be attached" in w for w in bundle.warnings))

    def test_mixer_notes_above_the_newest_shipped_version_are_hidden(self):
        self.put(
            "docs/updates/source/mixer-notes.md",
            MIXER_NOTES + "\n## [9.9.9]\n\n- Never shipped.\n",
        )
        bundle = self.build(release("1.0.0"))
        self.assertEqual([r["version"] for r in bundle.feed["mixer"]["releases"]], ["1.0.0"])
        self.assertNotIn("Never shipped", bundle.mixer_page)
        self.assertTrue(any("no published app release bundles it" in w for w in bundle.warnings))

    def test_pages_have_version_headings_and_cumulative_notes(self):
        bundle = self.build(
            release("1.0.0", date="2026-11-01"),
            release("1.1.0", date="2026-11-02"),
        )
        self.assertIn("## v1.1.0", bundle.app_page)
        self.assertIn("## v1.0.0", bundle.app_page)
        self.assertIn("Add the second thing", bundle.app_page)
        self.assertIn("Add the first thing", bundle.app_page)
        self.assertIn("[1.0.0](mixer.md#v1.0.0)", bundle.app_page)
        self.assertIn("lists every published app release from v1.0.0 to v1.1.0", bundle.app_page)
        self.assertIn("## v1.0.0", bundle.mixer_page)
        self.assertIn("[1.0.0](app.md#v1.0.0)", bundle.mixer_page)
        self.assertTrue(bundle.feed["app"]["historyComplete"])
        self.assertTrue(bundle.feed["mixer"]["historyComplete"])

    def test_the_single_release_wording_is_not_a_range(self):
        bundle = self.build(release("1.0.0"))
        self.assertIn("This history lists the published app release: v1.0.0.", bundle.app_page)
        self.assertIn(
            "This history records the mixer version bundled by published app releases: v1.0.0.",
            bundle.mixer_page,
        )

    def test_git_cliff_footer_never_becomes_a_note(self):
        bundle = self.build(release("1.0.0"), release("1.1.0"))
        notes = bundle.feed["app"]["releases"][0]["notesMarkdown"]
        self.assertNotIn("generated by git-cliff", notes)
        self.assertNotIn("generated by git-cliff", bundle.app_page)

    def test_notes_over_the_client_limit_stop_the_build(self):
        huge = "x" * (uh.MAX_NOTES_BYTES + 1)
        self.put("CHANGELOG.md", f"# Changelog\n\n## [1.0.0] - 2026-11-04\n\n{huge}\n")
        with self.assertRaisesRegex(uh.Problem, "at most"):
            self.build(release("1.0.0"))

    def test_folded_notes_over_the_client_limit_stop_the_build(self):
        first = "a" * (uh.MAX_NOTES_BYTES - 10)
        second = "b" * (uh.MAX_NOTES_BYTES - 10)
        self.put(
            "CHANGELOG.md",
            "# Changelog\n\n"
            f"## [1.2.0] - 2026-11-06\n\n- {second}\n\n"
            f"## [1.1.0] - 2026-11-05\n\n- {first}\n\n"
            "## [1.0.0] - 2026-11-04\n\n- First\n",
        )
        with self.assertRaisesRegex(uh.Problem, "at most"):
            self.build(release("1.0.0"), release("1.2.0"))

    def test_a_feed_over_the_client_limit_stops_the_build(self):
        with mock.patch.object(uh, "MAX_FEED_BYTES", 10):
            with self.assertRaisesRegex(uh.Problem, "updates.json is"):
                self.build(release("1.0.0"))

    def test_duplicate_and_non_stable_sections_fail(self):
        self.put("CHANGELOG.md", CHANGELOG + "\n## [1.0.0] - 2026-11-09\n\n- Again\n")
        with self.assertRaisesRegex(uh.Problem, "more than once"):
            self.build(release("1.0.0"))
        self.put("CHANGELOG.md", "# Changelog\n\n## [1.0] - 2026-11-04\n\n- Short version\n")
        with self.assertRaisesRegex(uh.Problem, "stable MAJOR.MINOR.PATCH"):
            self.build(release("1.0.0"))

    def test_published_entries_need_a_valid_date_and_must_be_unique(self):
        with self.assertRaisesRegex(uh.Problem, "no publication date"):
            uh.normalize_published(
                [{"tag_name": "v1.0.0", "draft": False, "prerelease": False}], "test"
            )
        with self.assertRaisesRegex(uh.Problem, "invalid publication date"):
            uh.normalize_published(
                [{"tag_name": "v1.0.0", "draft": False, "prerelease": False,
                  "published_at": "not-a-date"}], "test"
            )
        with self.assertRaisesRegex(uh.Problem, "appears more than once"):
            uh.normalize_published([release("1.0.0"), release("1.0.0")], "test")

    def test_the_tag_supplies_the_mapping(self):
        self.put("config/mixer-release.json", '{"version":"1.0.0","protocolVersion":2}')
        self.init_git()
        self.tag("1.0.0")
        bundle = self.build(release("1.0.0"), use_git=True)
        self.assertEqual(bundle.feed["app"]["releases"][0]["mixerVersion"], "1.0.0")
        self.assertEqual(bundle.feed["app"]["releases"][0]["protocolVersion"], 2)

    def test_a_tag_without_the_manifest_is_unknown_not_missing(self):
        self.init_git()
        self.tag("1.0.0")
        bundle = self.build(release("1.0.0"), use_git=True)
        self.assertIsNone(bundle.feed["app"]["releases"][0]["mixerVersion"])
        self.assertTrue(any("no recorded bundled mixer version" in w for w in bundle.warnings))

    def test_a_missing_tag_is_an_error(self):
        self.init_git()
        with self.assertRaisesRegex(uh.Problem, "is missing"):
            self.build(release("1.0.0"), use_git=True)

    def test_an_invalid_tag_manifest_fails(self):
        self.put("config/mixer-release.json", '{"version":"1.0","protocolVersion":2}')
        self.init_git()
        self.tag("1.0.0")
        with self.assertRaisesRegex(uh.Problem, "stable MAJOR.MINOR.PATCH"):
            self.build(release("1.0.0"), use_git=True)

    def test_cli_writes_the_feed_and_both_pages(self):
        self.put("config/mixer-release.json", '{"version":"1.0.0","protocolVersion":1}')
        self.init_git()
        self.tag("1.0.0")
        published = self.root / "published.json"
        published.write_text(json.dumps([release("1.0.0")]))
        out, err = io.StringIO(), io.StringIO()
        with redirect_stdout(out), redirect_stderr(err):
            code = uh.main(["--root", str(self.root), "--published-json", str(published)])
        self.assertEqual(code, 0)
        self.assertIn("1 app releases and 1 mixer versions", out.getvalue())
        feed = json.loads((self.root / "docs/public/updates.json").read_text())
        self.assertEqual(feed["app"]["releases"][0]["version"], "1.0.0")
        self.assertTrue((self.root / "docs/updates/app.md").is_file())
        self.assertTrue((self.root / "docs/updates/mixer.md").is_file())

    def test_a_source_error_exits_non_zero_without_writing(self):
        self.init_git()
        self.tag("2.0.0")
        published = self.root / "published.json"
        published.write_text(json.dumps([release("2.0.0")]))
        out, err = io.StringIO(), io.StringIO()
        with redirect_stdout(out), redirect_stderr(err):
            code = uh.main(["--root", str(self.root), "--published-json", str(published)])
        self.assertEqual(code, 1)
        self.assertIn("newest published release", err.getvalue())
        self.assertFalse((self.root / "docs/public/updates.json").exists())


if __name__ == "__main__":
    unittest.main()
